SELECT (SELECT COUNT(*) FROM bk_listing.listing_info WHERE deleted=0 AND total_price IS NOT NULL AND (asking_price_yuan IS NULL OR asking_price_yuan <> total_price * 10000))=0 AND (SELECT COUNT(*) FROM bk_listing.listing_info l WHERE l.deleted=0 AND l.total_price IS NOT NULL AND NOT EXISTS (SELECT 1 FROM bk_listing.listing_price_record p WHERE p.listing_id=l.id AND p.request_id='migration-baseline-20261105' AND p.operator_user_id=0))=0 AND (SELECT COUNT(*) FROM bk_listing.listing_info l WHERE l.deleted=0 AND NOT EXISTS (SELECT 1 FROM bk_listing.listing_status_record s WHERE s.listing_id=l.id AND s.request_id='migration-baseline-20261105' AND s.operator_user_id=0))=0;
